{"command":"python - << 'PY'
import itertools, sys

# literals representation: (var_index, sign) where sign=True for positive, False for neg
# We'll treat ℓ1,ℓ2,ℓ3 as vars 1,2,3. Aux vars 4,5.

vars = [1,2,3,4,5]

def eval_lit(assign, var, sign):
    val = assign[var]
    return val if sign else not val

def clause_satisfied(assign, clause):
    # clause is list of three (var, sign)
    vals = [eval_lit(assign, v, s) for v,s in clause]
    # NAE satisfied if not all equal
    return not (vals[0]==vals[1]==vals[2])

def formula_satisfied(assign, clauses):
    return all(clause_satisfied(assign, c) for c in clauses)

# generate all possible clause triples from literals set (allow each var at most once per clause, and not both var and its neg)
all_literals = []
for v in vars:
    all_literals.append((v, True))
    all_literals.append((v, False))

def valid_clause(triple):
    vars_in = [v for v,s in triple]
    if len(set(vars_in))<3:
        return False
    # cannot contain both v and ¬v -> check pairs
    for i in range(3):
        for j in range(i+1,3):
            if triple[i][0]==triple[j][0] and triple[i][1]!=triple[j][1]:
                return False
    return True

possible_clauses = [c for c in itertools.combinations(all_literals,3) if valid_clause(c)]

# search for gadget with up to 2 clauses
for num_clauses in [1,2]:
    for clauses in itertools.combinations(possible_clauses, num_clauses):
        # test condition: for every assignment to vars 1..3, there exists assignment to aux vars 4,5 such that formula satisfied iff original clause (OR) true.
        ok=True
        for assign_vals in itertools.product([False,True], repeat=5):
            assign = {i+1: assign_vals[i] for i in range(5)}
            # compute original clause satisfaction
            orig_sat = assign[1] or assign[2] or assign[3]
            # we need existence of aux assignment (variables 4,5) given fixed original vars to satisfy formula.
            # So we iterate over aux assignments.
            exists=False
            for aux_vals in itertools.product([False,True], repeat=2):
                assign2 = assign.copy()
                assign2[4]=aux_vals[0]
                assign2[5]=aux_vals[1]
                if formula_satisfied(assign2, clauses):
                    exists=True
                    break
            # condition: exists == orig_sat
            if exists != orig_sat:
                ok=False
                break
        if ok:
            print('Found gadget with', num_clauses, 'clauses')
            for c in clauses:
                print(c)
            raise SystemExit
print('none found')
PY"}

