import itertools, sys

orig_vars = [1,2,3]
max_aux = 3
max_clauses = 4

for aux_count in range(1, max_aux+1):
    aux_vars = list(range(4, 4+aux_count))
    all_vars = orig_vars + aux_vars
    # generate all possible literals
    literals = []
    for v in all_vars:
        literals.append((v, True))
        literals.append((v, False))
    def valid_clause(triple):
        vars_in = [v for v,s in triple]
        if len(set(vars_in))<3:
            return False
        for i in range(3):
            for j in range(i+1,3):
                if triple[i][0]==triple[j][0] and triple[i][1]!=triple[j][1]:
                    return False
        return True
    possible_clauses = [c for c in itertools.combinations(literals,3) if valid_clause(c)]
    for clause_count in range(1, max_clauses+1):
        for clauses in itertools.combinations(possible_clauses, clause_count):
            ok=True
            # for each assignment to original vars, need existence of aux assignment satisfying all NAE clauses iff OR true
            for orig_assign in itertools.product([False,True], repeat=3):
                assign_orig = {i+1: orig_assign[i] for i in range(3)}
                orig_sat = any(assign_orig[i] for i in [1,2,3])
                # check existence of aux assignment
                exists=False
                for aux_assign in itertools.product([False,True], repeat=aux_count):
                    assign = assign_orig.copy()
                    for idx, v in enumerate(aux_vars):
                        assign[v]=aux_assign[idx]
                    # evaluate NAE for each clause
                    def eval_lit(assign, var, sign):
                        val = assign[var]
                        return val if sign else not val
                    def nae_clause(cl):
                        vals = [eval_lit(assign, var, sign) for var,sign in cl]
                        return not (vals[0]==vals[1]==vals[2])
                    if all(nae_clause(cl) for cl in clauses):
                        exists=True
                        break
                if exists != orig_sat:
                    ok=False
                    break
            if ok:
                print('Found gadget with', aux_count, 'aux vars,', clause_count, 'clauses')
                print('aux vars', aux_vars)
                for cl in clauses:
                    print(cl)
                raise SystemExit
print('No gadget found up to limits')
