import itertools

def nae(vals):
    return not (vals[0]==vals[1]==vals[2])

def clause_sat(orig_clause, y):
    # orig_clause list of three literals (var, sign)
    # we will test reduction with two NAE clauses using y
    (a_sign,a_var),(b_sign,b_var),(c_sign,c_var)=orig_clause
    # produce NAE clauses: (a,b,y) and (¬a, ¬b, ¬y)
    def eval_lit(assign,var,sign):
        return assign[var] if sign else not assign[var]
    def eval(cl,assign):
        return nae([eval_lit(assign,var,sign) for var,sign in cl])
    # assign includes y variable
    cl1=[(a_var,a_sign),(b_var,b_sign),("y",True)]
    cl2=[(a_var,not a_sign),(b_var,not b_sign),("y",False)]
    return eval(cl1,assign) and eval(cl2,assign)
